/* global console */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import wordListPath from 'word-list';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const outputPath = resolve(repoRoot, 'packages/core/src/domain/word-chain-words.ts');
const words = readFileSync(wordListPath, 'utf8')
  .split('\n')
  .map((word) => word.trim().toLowerCase())
  .filter((word) => /^[a-z]{2,45}$/.test(word));

const source = `/**
 * Generated by scripts/generate-word-chain-lexicon.mjs from word-list 4.1.0.
 * word-list is an MIT-licensed SCOWL-derived English lexicon maintained by
 * Sindre Sorhus. Keep this file generated so client and server validate the
 * exact same vocabulary.
 */
export const WORD_CHAIN_WORDS_TEXT = \`${words.join('\n')}\`;
`;

writeFileSync(outputPath, source);
console.log(`Wrote ${words.length} words to ${outputPath}`);
